package ai.eva.android.probe;
import org.json.*;
/** Scope regression: DSH filtering must not affect manually configured API providers. */
public final class ModelProviderPolicyTest {
 static void check(boolean x,String m){if(!x)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
 long now=100000000;JSONArray rows=new JSONArray().put(new JSONObject().put("id","good").put("reasoningEfforts",new JSONArray().put("low").put("high"))).put(new JSONObject().put("id","bad")).put(new JSONObject().put("id","unknown"));JSONObject ledger=new JSONObject().put("good",new JSONObject().put("state","available").put("checkedAt",now)).put("bad",new JSONObject().put("state","unavailable").put("checkedAt",now));JSONObject p=new JSONObject().put("url",DshAvailability.URL).put("name","本机免费模型").put("model","bad").put("models",rows).put("manualModels",rows).put("modelAvailability",ledger);DshAvailability.decorate(p,now);check(p.getString("name").equals("DSH插件"),"rename");check(!p.has("description"),"no verbose DSH description");check(p.getJSONArray("models").length()==1&&p.getJSONArray("manualModels").length()==1,"only tested success, including manual fallback");check(p.getString("model").equals("bad"),"saved selection not silently changed");check(DshAvailability.visible(p,rows,now+DshAvailability.VALID_MS).length()==0,"stale success hidden");check(!DshAvailability.available(p,"good",now-1),"clock rollback not freshness");
 JSONObject other=new JSONObject().put("url","https://other.example/v1").put("models",rows);String original=other.toString();DshAvailability.decorate(other,now);check(other.toString().equals(original),"other providers unchanged");
 JSONArray spec=new JSONArray().put(new JSONObject().put("slug","deepseek-flash").put("default_reasoning_level","high").put("supported_reasoning_levels",new JSONArray().put(new JSONObject().put("effort","low")).put(new JSONObject().put("effort","high")).put(new JSONObject().put("effort","max"))));JSONObject deep=new JSONObject().put("url","https://api.deepseek.com").put("protocol","responses").put("model","deepseek-flash");ModelCapabilities.enrich(deep,spec);check(deep.getJSONArray("models").getJSONObject(0).getJSONArray("reasoningEfforts").length()==3,"manual DeepSeek without directory retains efforts");
 JSONObject fake=new JSONObject().put("url","https://api.deepseek.com.other.example").put("protocol","responses").put("model","deepseek-flash");ModelCapabilities.enrich(fake,spec);check(!fake.has("models"),"exact provider identity");JSONArray refreshed=new JSONArray().put(new JSONObject().put("id","good"));ModelCapabilities.retain(rows,refreshed);check(refreshed.getJSONObject(0).has("reasoningEfforts"),"refresh preserves known capabilities");JSONArray explicit=new JSONArray().put(new JSONObject().put("id","good").put("reasoningEfforts",new JSONArray()));ModelCapabilities.retain(rows,explicit);check(explicit.getJSONObject(0).getJSONArray("reasoningEfforts").length()==0,"explicit upstream capability removal honored");System.out.println("PASS DSH availability/expiry/scope and manual DeepSeek capability/refresh preservation");
 }
}
